-- Nupcial core schema, PostgreSQL 15+.
-- IDs are generated by the application with crypto.randomUUID().
-- No payment/card data belongs in this database. Billing remains external.
BEGIN;

CREATE TABLE IF NOT EXISTS schema_migrations (
  version text PRIMARY KEY,
  applied_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS accounts (
  id uuid PRIMARY KEY,
  email text NOT NULL,
  email_normalized text NOT NULL UNIQUE,
  password_hash text NOT NULL,
  status text NOT NULL DEFAULT 'pending_verification'
    CHECK (status IN ('pending_verification', 'active', 'suspended', 'closed')),
  email_verified_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CHECK (email_normalized = lower(btrim(email_normalized))),
  CHECK (length(password_hash) BETWEEN 20 AND 500)
);

CREATE TABLE IF NOT EXISTS account_sessions (
  id uuid PRIMARY KEY,
  account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  user_agent text,
  ip_hash text
);
CREATE INDEX IF NOT EXISTS account_sessions_active_idx
  ON account_sessions(account_id, expires_at) WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS email_verification_tokens (
  id uuid PRIMARY KEY,
  account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS email_verification_tokens_account_idx
  ON email_verification_tokens(account_id, expires_at);

CREATE TABLE IF NOT EXISTS password_reset_tokens (
  id uuid PRIMARY KEY,
  account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS password_reset_tokens_account_idx
  ON password_reset_tokens(account_id, expires_at);

CREATE TABLE IF NOT EXISTS events (
  id uuid PRIMARY KEY,
  owner_account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
  slug text NOT NULL UNIQUE,
  status text NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'published', 'archived', 'closed')),
  bride_name text NOT NULL DEFAULT '',
  groom_name text NOT NULL DEFAULT '',
  event_date date,
  ceremony_time time,
  reception_time time,
  venue text NOT NULL DEFAULT '',
  venue_address text NOT NULL DEFAULT '',
  phrase text NOT NULL DEFAULT '',
  dress_code text NOT NULL DEFAULT '',
  rsvp_deadline date,
  theme_key text NOT NULL DEFAULT 'versalles',
  palette_key text NOT NULL DEFAULT 'dorado',
  content jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(content) = 'object'),
  sections jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(sections) = 'object'),
  timezone text NOT NULL DEFAULT 'America/Lima',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz,
  UNIQUE (owner_account_id, id)
);
CREATE INDEX IF NOT EXISTS events_owner_updated_idx ON events(owner_account_id, updated_at DESC);
CREATE INDEX IF NOT EXISTS events_published_slug_idx ON events(slug) WHERE status = 'published';

-- Extra editors/viewers. Event owner is events.owner_account_id.
CREATE TABLE IF NOT EXISTS event_memberships (
  event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  account_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  role text NOT NULL CHECK (role IN ('editor', 'viewer')),
  invited_by_account_id uuid REFERENCES accounts(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (event_id, account_id)
);
CREATE INDEX IF NOT EXISTS event_memberships_account_idx ON event_memberships(account_id, event_id);

CREATE TABLE IF NOT EXISTS event_itinerary_items (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  sort_order integer NOT NULL CHECK (sort_order >= 0),
  event_time time,
  icon_key text NOT NULL DEFAULT 'clock',
  title text NOT NULL CHECK (length(btrim(title)) > 0),
  description text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (event_id, sort_order),
  UNIQUE (event_id, id)
);
CREATE INDEX IF NOT EXISTS event_itinerary_order_idx ON event_itinerary_items(event_id, sort_order);

CREATE TABLE IF NOT EXISTS event_gift_options (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  sort_order integer NOT NULL CHECK (sort_order >= 0),
  gift_type text NOT NULL CHECK (gift_type IN ('registry', 'transfer', 'honeymoon', 'other')),
  title text NOT NULL CHECK (length(btrim(title)) > 0),
  detail text NOT NULL DEFAULT '',
  url text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (event_id, sort_order),
  UNIQUE (event_id, id)
);
CREATE INDEX IF NOT EXISTS event_gift_options_order_idx ON event_gift_options(event_id, sort_order);

CREATE TABLE IF NOT EXISTS guest_groups (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  -- Opaque URL token: generate >= 24 random bytes (base64url); never encode PII.
  link_code text NOT NULL UNIQUE CHECK (length(link_code) BETWEEN 32 AND 128),
  display_name text NOT NULL CHECK (length(btrim(display_name)) > 0),
  contact_email text,
  contact_phone text,
  invitation_type text NOT NULL DEFAULT 'group' CHECK (invitation_type IN ('individual', 'group')),
  category text NOT NULL DEFAULT '',
  side text NOT NULL DEFAULT '',
  pass_limit integer NOT NULL DEFAULT 1 CHECK (pass_limit BETWEEN 1 AND 20),
  notes text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  UNIQUE (event_id, id)
);
CREATE INDEX IF NOT EXISTS guest_groups_event_name_idx ON guest_groups(event_id, lower(display_name)) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS guest_groups_event_category_idx ON guest_groups(event_id, category) WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS guest_rsvp_responses (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL,
  guest_group_id uuid NOT NULL,
  response_status text NOT NULL CHECK (response_status IN ('confirmed', 'declined')),
  attendee_count integer NOT NULL CHECK (attendee_count BETWEEN 0 AND 20),
  attendance_type text NOT NULL DEFAULT 'full' CHECK (attendance_type IN ('ceremony', 'full')),
  message text NOT NULL DEFAULT '' CHECK (length(message) <= 500),
  responded_at timestamptz NOT NULL DEFAULT now(),
  source text NOT NULL DEFAULT 'guest_link' CHECK (source IN ('guest_link', 'client_manual', 'import')),
  FOREIGN KEY (event_id, guest_group_id) REFERENCES guest_groups(event_id, id) ON DELETE CASCADE,
  UNIQUE (event_id, id),
  CHECK ((response_status = 'declined' AND attendee_count = 0) OR (response_status = 'confirmed' AND attendee_count BETWEEN 1 AND 20))
);
CREATE INDEX IF NOT EXISTS guest_rsvp_history_idx ON guest_rsvp_responses(event_id, guest_group_id, responded_at DESC);

CREATE TABLE IF NOT EXISTS guest_rsvp_attendees (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL,
  response_id uuid NOT NULL,
  sort_order integer NOT NULL CHECK (sort_order >= 0),
  display_name text NOT NULL CHECK (length(btrim(display_name)) > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (event_id, response_id) REFERENCES guest_rsvp_responses(event_id, id) ON DELETE CASCADE,
  UNIQUE (event_id, response_id, sort_order),
  UNIQUE (event_id, id)
);
CREATE INDEX IF NOT EXISTS guest_rsvp_attendees_response_idx ON guest_rsvp_attendees(event_id, response_id, sort_order);

-- Latest RSVP per invitation group; history stays in guest_rsvp_responses.
CREATE OR REPLACE VIEW current_guest_rsvps AS
SELECT DISTINCT ON (event_id, guest_group_id)
  event_id, guest_group_id, id AS response_id, response_status, attendee_count,
  attendance_type, message, responded_at, source
FROM guest_rsvp_responses
ORDER BY event_id, guest_group_id, responded_at DESC, id DESC;

CREATE TABLE IF NOT EXISTS event_tables (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  name text NOT NULL CHECK (length(btrim(name)) > 0),
  capacity integer NOT NULL CHECK (capacity BETWEEN 1 AND 20),
  shape text NOT NULL DEFAULT 'round' CHECK (shape IN ('round', 'square', 'rectangle')),
  position_x numeric(6,3) NOT NULL DEFAULT 50 CHECK (position_x BETWEEN 0 AND 100),
  position_y numeric(6,3) NOT NULL DEFAULT 50 CHECK (position_y BETWEEN 0 AND 100),
  rotation numeric(6,2) NOT NULL DEFAULT 0 CHECK (rotation BETWEEN 0 AND 360),
  sort_order integer NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (event_id, id),
  UNIQUE (event_id, name)
);
CREATE INDEX IF NOT EXISTS event_tables_order_idx ON event_tables(event_id, sort_order);

-- One invitation group can be at most one table; one table can contain many groups.
-- Capacity checks must run transactionally in the application before insert/update.
CREATE TABLE IF NOT EXISTS guest_table_assignments (
  event_id uuid NOT NULL,
  guest_group_id uuid NOT NULL,
  table_id uuid NOT NULL,
  assigned_by_account_id uuid REFERENCES accounts(id) ON DELETE SET NULL,
  assigned_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (event_id, guest_group_id),
  FOREIGN KEY (event_id, guest_group_id) REFERENCES guest_groups(event_id, id) ON DELETE CASCADE,
  FOREIGN KEY (event_id, table_id) REFERENCES event_tables(event_id, id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS guest_table_assignments_table_idx ON guest_table_assignments(event_id, table_id);

CREATE TABLE IF NOT EXISTS event_floor_objects (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  object_type text NOT NULL CHECK (object_type IN ('dance_floor', 'entrance', 'dj', 'bar', 'stage', 'custom')),
  label text NOT NULL DEFAULT '',
  position_x numeric(6,3) NOT NULL DEFAULT 50 CHECK (position_x BETWEEN 0 AND 100),
  position_y numeric(6,3) NOT NULL DEFAULT 50 CHECK (position_y BETWEEN 0 AND 100),
  width numeric(6,3) NOT NULL DEFAULT 10 CHECK (width BETWEEN 1 AND 100),
  height numeric(6,3) NOT NULL DEFAULT 10 CHECK (height BETWEEN 1 AND 100),
  rotation numeric(6,2) NOT NULL DEFAULT 0 CHECK (rotation BETWEEN 0 AND 360),
  sort_order integer NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (event_id, id)
);
CREATE INDEX IF NOT EXISTS event_floor_objects_order_idx ON event_floor_objects(event_id, sort_order);

CREATE TABLE IF NOT EXISTS event_song_suggestions (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  title text NOT NULL CHECK (length(btrim(title)) > 0),
  artist text NOT NULL CHECK (length(btrim(artist)) > 0),
  requester text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
  moderated_by_account_id uuid REFERENCES accounts(id) ON DELETE SET NULL,
  moderated_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (event_id, id)
);
CREATE INDEX IF NOT EXISTS event_song_suggestions_queue_idx ON event_song_suggestions(event_id, status, created_at DESC);

-- Media bytes live in private object storage, not in PostgreSQL/base64 payloads.
CREATE TABLE IF NOT EXISTS event_media (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  uploaded_by_guest_group_id uuid,
  media_kind text NOT NULL CHECK (media_kind IN ('cover', 'music', 'gallery')),
  object_key text NOT NULL UNIQUE,
  mime_type text NOT NULL,
  byte_size bigint NOT NULL CHECK (byte_size BETWEEN 1 AND 52428800),
  moderation_status text NOT NULL DEFAULT 'approved' CHECK (moderation_status IN ('pending', 'approved', 'rejected')),
  sort_order integer NOT NULL DEFAULT 0 CHECK (sort_order >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  FOREIGN KEY (event_id, uploaded_by_guest_group_id) REFERENCES guest_groups(event_id, id) ON DELETE SET NULL (uploaded_by_guest_group_id),
  UNIQUE (event_id, id)
);
CREATE INDEX IF NOT EXISTS event_media_gallery_idx ON event_media(event_id, media_kind, moderation_status, sort_order) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS event_media_single_cover_idx ON event_media(event_id) WHERE media_kind = 'cover' AND deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS event_media_single_music_idx ON event_media(event_id) WHERE media_kind = 'music' AND deleted_at IS NULL;

-- The separate billing service owns orders/payments. This app stores entitlements only.
CREATE TABLE IF NOT EXISTS event_entitlements (
  event_id uuid PRIMARY KEY REFERENCES events(id) ON DELETE CASCADE,
  plan_code text NOT NULL CHECK (plan_code IN ('essential', 'premium', 'deluxe')),
  status text NOT NULL CHECK (status IN ('demo', 'active', 'grace', 'suspended', 'expired', 'cancelled')),
  billing_service text NOT NULL,
  external_entitlement_id text NOT NULL UNIQUE,
  effective_at timestamptz NOT NULL,
  expires_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS billing_event_receipts (
  external_event_id text PRIMARY KEY,
  event_id uuid REFERENCES events(id) ON DELETE SET NULL,
  signature_verified boolean NOT NULL,
  processing_status text NOT NULL CHECK (processing_status IN ('processed', 'ignored', 'failed')),
  received_at timestamptz NOT NULL DEFAULT now(),
  processed_at timestamptz,
  payload_sha256 text
);
CREATE INDEX IF NOT EXISTS billing_event_receipts_event_idx ON billing_event_receipts(event_id, received_at DESC);

CREATE TABLE IF NOT EXISTS event_activity_log (
  id uuid PRIMARY KEY,
  event_id uuid NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  actor_account_id uuid REFERENCES accounts(id) ON DELETE SET NULL,
  action text NOT NULL,
  entity_type text NOT NULL,
  entity_id uuid,
  request_id text,
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(metadata) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS event_activity_log_event_idx ON event_activity_log(event_id, created_at DESC);

INSERT INTO schema_migrations(version) VALUES ('001_core_schema') ON CONFLICT (version) DO NOTHING;
COMMIT;
